def paired_metrics(frame, reference, prediction):
    observed = frame[reference].to_numpy(dtype=float)
    predicted = frame[prediction].to_numpy(dtype=float)
    assert np.isfinite(observed).all() and np.isfinite(predicted).all(), "Shared sample must be finite."
    if len(frame) == 0:
        return {"n": 0, **{name: np.nan for name in METRICS if name != "n"}}
    result = calculate_metrics(observed, predicted)
    result["bias"] = result.pop("BIAS")
    centered = observed - observed.mean()
    denominator = np.dot(centered, centered)
    if len(frame) >= 2 and denominator > 0:
        slope = np.dot(centered, predicted - predicted.mean()) / denominator
        result.update(slope=float(slope), intercept=float(predicted.mean() - slope * observed.mean()))
    else:
        result.update(R2=np.nan, slope=np.nan, intercept=np.nan)
    assert result["n"] == len(frame), "Metric function changed the shared sample."
    return {name: result[name] for name in METRICS}

main_metrics = pd.DataFrame([
    {"product": label, **paired_metrics(common, REFERENCE, column)}
    for label, column in PRODUCTS.items()
])
assert main_metrics.n.eq(len(common)).all()
display(main_metrics)
